 "content": "def transform(grid):
    # Background is the most common cell; fill each one-cell gap between
    # matching non-background marks with color 2.
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        for c in range(1, len(row) - 1):
            if row[c] == bg and row[c - 1] == row[c + 1] and row[c - 1] != bg:
                out[r][c] = 2
    return out
